  constructor(options = {}) { this.now = options.now || (() => Date.now()); this.minHoldMs = Math.max(5000, Math.min(10 * 60 * 1000, Number(options.minHoldMs) || 30000)); this.lastAura = null; this.lastChangedAt = 0; this.lastDecision = null; }
