    if (risk.unknown || risk.highRisk || risk.lowSurvivalMargin) { aura = damageType === 'magical' ? 'sanctuary' : 'bulwark'; reason = damageType === 'magical' ? 'MAGICAL_DAMAGE_PRESSURE' : 'LOW_SURVIVAL_MARGIN'; }
