    this.stats.attempts += 1;
    const before = this._snapshot(tx);
    this._event('CONTROLLED_BANK_EXPANSION_STARTED', 'warn', 'CONTROLLED_CANARY', { transactionId: tx.id, pack: tx.pack, currency: tx.currency, cost: tx.cost, before });
