    this.failureWindowMs = Math.max(60 * 1000, Math.min(60 * 60 * 1000, Number(options.failureWindowMs) || 10 * 60 * 1000));
    this.failureThreshold = Math.max(2, Math.min(10, Number(options.failureThreshold) || 3));
