        this.stats.kiteCohesionBlocks += 1;
        this.lastDecision = { at: this.now(), action: 'KITE_HOLD', reason: 'TEAM_COHESION_KITE_LIMIT', targetId: target && target.id || null, leaderName: team.leaderName };
